from verify_u0a_butterfly_formula_compiler import formulas
# replay v2 find swap both occupancy and collect formula
for n in range(2,7):
 found=None
 for f in formulas(n,3):
  p=compile_formula_sparse(f,width=8 if n>4 else 4,certificate_version='v2')
  st=dict(p['event_certificate']['initial_token_map'])
  for e in p['event_certificate']['events']:
   if e['kind']=='SWAP':
    x,y=e['lanes']; toks=[t for t,l in st.items() if l in (x,y)]
    if len(toks)==2: found=(f,e,dict(st)); break
    # apply
    for tok in st:
     if st[tok]==x:st[tok]=y
     elif st[tok]==y:st[tok]=x
   elif e['kind']=='DUPLICATE':
    s,new,x,y=e['semantic'];st[new]=y
   elif e['kind']=='NAND':
    l,r,o,x,y=e['semantic'];del st[l];del st[r];st[o]=x
  if found:break
 print(n, found and found[:2])
 if found: break

